    # Update reputation based on observed action with recency weighting
    if observation['action'] == 'cooperate':
        delta = 0.4  # Positive update for cooperation
    else:
        delta = -0.4  # Negative update for defection

    # Apply recency decay (more weight to recent observations)
    decay = 0.92
    new_reputation = (current_reputation * decay) + delta

    # Clamp reputation to valid range [-1.0, 1.0]
    new_reputation = max(-1.0, min(1.0, new_reputation))

    return new_reputation

